#!/usr/bin/env node
// Regenerates the source-suite inventory (Section 7) in an aggregator suite's
// test plan from the tests its config ACTUALLY selects, rather than trusting a
// hand-maintained table.
//
// An aggregator suite's membership is dynamic -- any test tagged @regression in
// any suite joins it automatically -- so a table listing suites and counts goes
// stale the moment a new suite is generated, with nothing to catch it. This
// script makes Section 7 a generated artifact instead: pipeline-execute.yml
// runs it on every aggregator execution and commits the result alongside that
// run's results data.
//
// Section 7 is deliberately the ONLY place in the plan that carries counts, so
// this one regenerated block keeps the whole document accurate.
//
// Usage: node sync-regression-inventory.js <slug>
// Exits 1 if the plan has no inventory markers or the suite config is missing.

const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const BEGIN = "<!-- BEGIN:REGRESSION-INVENTORY -->";
const END = "<!-- END:REGRESSION-INVENTORY -->";

const [, , slug] = process.argv;

if (!slug || !/^[a-z0-9][a-z0-9-]*$/.test(slug)) {
  console.error("Usage: node sync-regression-inventory.js <slug>  (slug: lowercase letters, digits, hyphens)");
  process.exit(1);
}

const configPath = path.join("tests", slug, "suite.config.ts");
const planPath = path.join("specs", `${slug}-test-plan.md`);

if (!fs.existsSync(configPath)) {
  console.error(`${configPath} not found -- ${slug} is not an aggregator suite, nothing to sync.`);
  process.exit(1);
}
if (!fs.existsSync(planPath)) {
  console.error(`${planPath} not found.`);
  process.exit(1);
}

// Ask Playwright what the config selects. --list resolves the same grep and
// testDir the real run uses, so the inventory can't disagree with the run.
const raw = execSync(
  `npx playwright test --config="${configPath}" --project=chromium --list --reporter=json`,
  { encoding: "utf8", maxBuffer: 256 * 1024 * 1024, stdio: ["ignore", "pipe", "inherit"] }
);

const report = JSON.parse(raw);

// Playwright nests describe blocks arbitrarily deep; specs can appear at any
// level, so walk the whole tree rather than assuming a fixed shape.
const counts = new Map();
function walk(node) {
  for (const spec of node.specs ?? []) {
    const file = node.file ?? spec.file ?? "";
    const suite = file.split(/[\\/]/)[0];
    if (!suite) continue;
    counts.set(suite, (counts.get(suite) ?? 0) + (spec.tests?.length || 1));
  }
  for (const child of node.suites ?? []) walk({ ...child, file: child.file ?? node.file });
}
for (const s of report.suites ?? []) walk(s);

if (counts.size === 0) {
  console.error("The suite config selected no tests -- refusing to write an empty inventory.");
  process.exit(1);
}

function isTiered(suite) {
  const p = path.join("specs", `${suite}-test-plan.md`);
  return fs.existsSync(p) && fs.readFileSync(p, "utf8").includes("**Tier:**");
}

// The application each suite targets isn't recorded anywhere structured, so
// derive it: the URL appearing most often in that suite's sources is the one
// it drives.
function appUrl(suite) {
  const dir = path.join("tests", suite);
  const freq = new Map();
  const stack = [dir];
  while (stack.length) {
    const cur = stack.pop();
    if (!fs.existsSync(cur)) continue;
    for (const e of fs.readdirSync(cur, { withFileTypes: true })) {
      const full = path.join(cur, e.name);
      if (e.isDirectory()) stack.push(full);
      else if (e.name.endsWith(".ts")) {
        for (const m of fs.readFileSync(full, "utf8").matchAll(/https?:\/\/[^\s'"`)]+/g)) {
          const url = m[0].replace(/[.,]+$/, "").replace(/\/$/, "");
          freq.set(url, (freq.get(url) ?? 0) + 1);
        }
      }
    }
  }
  if (freq.size === 0) return "—";
  const best = [...freq.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0][0];
  return best.replace(/^https?:\/\//, "");
}

const rows = [...counts.entries()]
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
  .map(([suite, tests]) => ({ suite, tests, tiered: isTiered(suite), url: appUrl(suite) }));

const totalTests = rows.reduce((n, r) => n + r.tests, 0);
const tiered = rows.filter((r) => r.tiered);
const untiered = rows.filter((r) => !r.tiered);
const tieredTests = tiered.reduce((n, r) => n + r.tests, 0);

const lines = [
  BEGIN,
  "",
  "<!-- Generated by .github/scripts/sync-regression-inventory.js on each",
  "     execution of this suite. Do not edit by hand -- edits are overwritten. -->",
  "",
  "| # | Source Suite | Application Under Test | Tests | Tiered |",
  "|---|---|---|---|---|",
  ...rows.map(
    (r, i) => `| ${i + 1} | \`${r.suite}\` | ${r.url} | ${r.tests} | ${r.tiered ? "Yes" : "No"} |`
  ),
  `| | **Total** | **${rows.length} suites** | **${totalTests}** | **${tieredTests} tiered** |`,
  "",
  '"Tiered" indicates whether that suite\'s own test plan classifies its cases',
  `as Smoke / Sanity / Functional. ${tiered.length} suite(s) (${tieredTests} tests) do; the`,
  `remaining ${untiered.length} (${totalTests - tieredTests} tests) predate that classification and carry`,
  "no tier. All are part of the regression set regardless — tier depth and",
  "regression membership are independent properties.",
  "",
  END,
];

const plan = fs.readFileSync(planPath, "utf8");
const beginIdx = plan.indexOf(BEGIN);
const endIdx = plan.indexOf(END);
if (beginIdx === -1 || endIdx === -1 || endIdx < beginIdx) {
  console.error(`${planPath} has no ${BEGIN} / ${END} block to regenerate.`);
  process.exit(1);
}

const updated = plan.slice(0, beginIdx) + lines.join("\n") + plan.slice(endIdx + END.length);

if (updated === plan) {
  console.log(`Inventory already up to date: ${rows.length} suites, ${totalTests} tests.`);
} else {
  fs.writeFileSync(planPath, updated);
  console.log(`Rewrote ${planPath}: ${rows.length} suites, ${totalTests} tests (${tieredTests} tiered).`);
}
